import ast,pathlib
mf=(0,"");mfn=(0,"")
for p in list(pathlib.Path('.claude').rglob('*.py'))+list(pathlib.Path('tools').rglob('*.py')):
    if 'worktrees' in p.parts or p.name.startswith('test_') or p.name=='conftest.py': continue
    t=p.read_text(encoding='utf-8');n=t.count('\n')+1
    if n>mf[0]:mf=(n,str(p))
    for f in ast.walk(ast.parse(t)):
        if isinstance(f,(ast.FunctionDef,ast.AsyncFunctionDef)):
            l=f.end_lineno-f.lineno+1
            if l>mfn[0]:mfn=(l,f"{p}:{f.name}")
print(mf,mfn)
E
